DROP ASYNC REPLICATION r CASCADE;
DROP ASYNC REPLICATION r;
drop async replication `cascade`;
DROP TOPIC IF EXISTS `app/events`;
ALTER TOPIC `app/events` ADD CONSUMER a, DROP CONSUMER b;
ALTER TOPIC `app/events` ADD CONSUMER a;
DROP TRANSFER t;
DROP COORDINATION NODE `app/locks`;
DROP SECRET `app/token`;
DROP STREAMING QUERY q;
ALTER STREAMING QUERY q SET (RUN = FALSE);
ALTER STREAMING QUERY q SET (FORCE = TRUE) AS DO BEGIN SELECT 1; END DO;
DROP EXTERNAL DATA SOURCE s;
DROP EXTERNAL TABLE e;
CREATE OR REPLACE EXTERNAL TABLE e (a Int32) WITH (DATA_SOURCE = "s", LOCATION = "/");
DROP TABLE t;
DROP COORDINATION SEMAPHORE `app/locks`;
ALTER TABLE t DROP CONSUMER;
